<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
import { storageKey } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import ConfirmDialog from './ui/ConfirmDialog.vue'
const items=ref([]),quotes=ref([]),balance=ref(0),error=ref(''),choice=ref(null),writes=useWorkflowWrite('reward-shop'),form=ref({name:'',reward_kind:'item',minutes:30,price_yuan:null,description:''}),manual=ref({})
const key=storageKey('reward-draft')
try{form.value={...form.value,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{}
function cache(){localStorage.setItem(key,JSON.stringify(form.value))}
async function load(){try{const [shop,q]=await Promise.all([api.listShopItems(),api.flow('/reward-quotes')]);items.value=shop.items;balance.value=shop.balance;quotes.value=q.items}catch(e){error.value=e.message}}
async function act(path,body,method='POST'){try{await writes.send(path,body,method);await load();error.value=''}catch(e){error.value=e.message}}
async function price(item=null){cache();await act('/reward-quotes',item?{name:item.name,reward_kind:item.reward_kind||'item',minutes:Math.max(1,(item.duration_seconds||1800)/60),price_yuan:item.price_yuan,item_id:item.id,item_version:item.updated_at}:form.value)}
async function redeem(){const item=choice.value;if(!item)return;await act('/shop/items/'+item.id+'/redeem',{expected_version:item.updated_at});if(!error.value)choice.value=null}
onMounted(load)
</script>
<template><section class="card"><h2>添加想要的奖励</h2><p class="muted">填写内容，主动请求 AI 建议价格；将使用你授权的问卷、阶段、当前主线，以及确认收入、购买与实际使用。接受才加入商店，必要休息无需兑换。</p><p v-if="error" class="error" role="alert">{{ error }}</p><button v-if="writes.pending.value" class="btn" :disabled="writes.busy.value" @click="act(writes.pending.value.path,writes.pending.value.body,writes.pending.value.method)">恢复上次请求</button><button v-if="writes.pending.value?.path==='/reward-quotes'" class="btn" :disabled="writes.busy.value" @click="writes.discardSuggestion()">保留草稿，结束本次价格请求</button><form @submit.prevent="price()" @input="cache"><label>奖励名称<input v-model="form.name" maxlength="120" required/></label><label>类型<select v-model="form.reward_kind"><option value="item">物品</option><option value="experience">体验</option><option value="entertainment">计时娱乐</option></select></label><label v-if="form.reward_kind==='entertainment'">每次分钟<input type="number" min="1" max="1440" v-model.number="form.minutes"/></label><label>现实价格（可空）<input type="number" min="0" step="0.01" v-model.number="form.price_yuan"/></label><label>说明与期望频率<textarea v-model="form.description" maxlength="2000"/></label><button class="btn" :disabled="writes.busy.value||!!writes.pending.value">请求 AI 价格建议</button></form><article v-for="quote in quotes.filter(q=>q.state==='suggested')" :key="quote.id"><h3>{{ quote.payload.name }} · 建议 {{ quote.result.coin_price }} 币</h3><p>{{ quote.result.pricing_reason }}</p><p>{{ quote.result.worth_note }}</p><p v-if="quote.result.bounds">本次允许范围 {{ quote.result.bounds[0] }}～{{ quote.result.bounds[1] }}；每日最多应用一次。</p><button class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="act('/reward-quotes/'+quote.id+'/accept',{expected_version:quote.version})">接受{{ quote.item_id?'改价建议':'并加入商店' }}</button></article></section><section class="card"><h2>奖励商店 · {{ balance }} 币</h2><RouterLink to="/timers">娱乐券与计时 →</RouterLink><article v-for="item in items" :key="item.id"><h3>{{ item.name }} · {{ item.coin_price }} 币</h3><p>{{ item.pricing_reason }}</p><p v-if="!item.reward_kind" class="muted">旧商品保留原权益；基础休息无需兑换。</p><div class="action-group"><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!item.enabled||balance<item.coin_price" @click="choice=item">兑换</button><button class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="price(item)">建议涨价 / 降价</button></div><details><summary>手动修正后续价格 / 恢复基础价</summary><label>后续金币价<input type="number" min="1" v-model.number="manual[item.id]"/></label><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!manual[item.id]" @click="act('/shop/items/'+item.id,{coin_price:manual[item.id]},'PUT')">保存手动修正</button><button v-if="item.base_coin_price" class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="act('/shop/items/'+item.id,{coin_price:item.base_coin_price},'PUT')">恢复确认基础价</button></details></article></section><ConfirmDialog :open="!!choice" title="确认兑换" :busy="writes.busy.value" @cancel="choice=null" @confirm="redeem"><p>用 {{ choice?.coin_price }} 币兑换 {{ choice?.name }}，购买锁定本券额度及价格。</p></ConfirmDialog></template>
